<template>
  <SidebarLayout title="Browse Treks" subtitle="Explore Treks" user="Trekker" :links="links"><div class="panel"><div class="row g-3"><div class="col-md-3"><input v-model="search" class="form-control" placeholder="Search treks..."></div><div class="col-md-3"><select v-model="difficulty" class="form-select"><option value="">Difficulty: All</option><option>Easy</option><option>Moderate</option><option>Hard</option></select></div><div class="col-md-3"><input v-model="location" class="form-control" placeholder="Location"></div><div class="col-md-3"><input v-model="duration" type="number" min="1" class="form-control" placeholder="Duration (days)"></div></div></div><div class="three-col mt-4"><TrekCard v-for="trek in treks" :key="trek.id" :trek="trek" action-text="Book Now" :disabled="trek.status !== 'open' || trek.available_slots <= 0" @action="openCheckout" /></div><div v-if="selectedTrek" class="modal fade show d-block" tabindex="-1" style="background:rgba(0,0,0,.35)"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">Checkout - {{ selectedTrek.trek_name }}</h5><button type="button" class="btn-close" @click="closeCheckout"></button></div><div class="modal-body"><div class="mb-3"><label class="form-label">Payment Method</label><select v-model="checkout.payment_method" class="form-select" required><option value="">Select method</option><option>UPI</option><option>Card</option><option>Wallet</option></select></div><div class="mb-3"><label class="form-label">Transaction Status</label><select v-model="checkout.payment_status" class="form-select"><option>simulated-paid</option><option>failed</option></select></div><div class="alert alert-info">State: {{ checkout.state }}</div></div><div class="modal-footer"><button class="btn btn-outline-secondary" @click="closeCheckout">Cancel</button><button class="btn btn-primary" :disabled="checkout.state==='processing'" @click="confirmCheckout">{{ checkout.state==='processing' ? 'Processing...' : 'Confirm Payment & Book' }}</button></div></div></div></div></SidebarLayout>
</template>
<script setup>
import { onMounted, ref, watch, reactive } from 'vue'
import { useRouter } from 'vue-router'
import SidebarLayout from '../components/SidebarLayout.vue'
import TrekCard from '../components/TrekCard.vue'
import { userApi, authApi } from '../services/api'
const router=useRouter(); const logout = async()=>{ await authApi.logout(); router.push('/login') }
const links=[{label:'Dashboard',to:'/user/dashboard',icon:'bi bi-grid'},{label:'Browse Treks',to:'/user/treks',icon:'bi bi-compass'},{label:'History',to:'/user/history',icon:'bi bi-clock-history'},{label:'Profile',to:'/user/profile',icon:'bi bi-person-circle'},{label:'Logout',icon:'bi bi-box-arrow-right',action:logout}]
const treks=ref([]); const search=ref(''); const difficulty=ref(''); const location=ref(''); const duration=ref(''); const selectedTrek=ref(null)
const checkout=reactive({ payment_method:'', payment_status:'simulated-paid', transaction_id:'', state:'idle' })
let timer = null
async function load(){ const params=`?q=${encodeURIComponent(search.value)}&difficulty=${encodeURIComponent(difficulty.value)}&location=${encodeURIComponent(location.value)}&duration=${encodeURIComponent(duration.value)}`; treks.value=(await userApi.treks(params)).data.items }
function openCheckout(trek){ selectedTrek.value = trek; checkout.payment_method=''; checkout.payment_status='simulated-paid'; checkout.transaction_id=`TXN-${Date.now()}-${trek.id}`; checkout.state='review' }
function closeCheckout(){ selectedTrek.value=null; checkout.state='idle' }
async function confirmCheckout(){ if(!checkout.payment_method){ alert('Select a payment method.'); return } checkout.state='processing'; try { await userApi.book({ trek_id: selectedTrek.value.id, payment_status: checkout.payment_status, payment_method: checkout.payment_method, transaction_id: checkout.transaction_id }); checkout.state='success'; alert('Booking created successfully with simulated payment.'); closeCheckout(); await load() } catch(e){ checkout.state='failed'; alert(e?.response?.data?.error || (e?.response?.data?.errors || []).join(', ') || 'Booking failed.') } }
watch([search,difficulty,location,duration], ()=>{ clearTimeout(timer); timer = setTimeout(load, 350) })
onMounted(load)
</script>
